const ALERT_PCT = 1.00; // 🚨 alert if a coin moves this % or more since the last run

const r = $input.first().json.result;
const state = $getWorkflowStaticData('global'); // remembered between scheduled runs
const prev = state.lastPrices || {};

const coins = [
  { key: 'XXBTZEUR', name: 'Bitcoin', symbol: 'BTC' },
  { key: 'XETHZEUR', name: 'Ethereum', symbol: 'ETH' },
];

const eur = new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' });
const fmtPct = p => (p >= 0 ? '+' : '') + p.toFixed(2) + '%';

const data = coins.map(c => {
  const t = r[c.key];
  const price = parseFloat(t.c[0]);
  const open = parseFloat(t.o);
  const high24h = parseFloat(t.h[1]);
  const low24h = parseFloat(t.l[1]);
  const changePct = ((price - open) / open) * 100;
  const prevPrice = prev[c.symbol];
  const sinceLastPct = prevPrice ? ((price - prevPrice) / prevPrice) * 100 : null;
  const alert = sinceLastPct !== null && Math.abs(sinceLastPct) >= ALERT_PCT;
  return {
    symbol: c.symbol, name: c.name, price, open, high24h, low24h,
    changePct: Number(changePct.toFixed(2)),
    sinceLastPct: sinceLastPct === null ? null : Number(sinceLastPct.toFixed(2)),
    alert,
  };
});

// save current prices for the next run
state.lastPrices = Object.fromEntries(data.map(d => [d.symbol, d.price]));
state.lastRun = new Date().toISOString();

const time = new Date().toLocaleString('de-DE', {
  timeZone: 'Europe/Berlin', dateStyle: 'short', timeStyle: 'short',
});

const lines = data.map(d => {
  const icon = d.alert ? '🚨' : (d.changePct >= 0 ? '🟢' : '🔴');
  const last = d.sinceLastPct === null ? 'first run' : `${fmtPct(d.sinceLastPct)} since last update`;
  return `${icon} ${d.symbol}: ${eur.format(d.price)}\n` +
         `   ${fmtPct(d.changePct)} today · ${last}\n` +
         `   24h range: ${eur.format(d.low24h)} – ${eur.format(d.high24h)}`;
});

const anyAlert = data.some(d => d.alert);
const header = anyAlert
  ? `🚨 BIG MOVE (≥ ${ALERT_PCT}% since last update)\n`
  : '';

const message = `${header}📊 Crypto update – ${time}\n\n${lines.join('\n\n')}`;

return [{ json: { time, anyAlert, coins: data, message } }];
